-- NFL players overall>=76: mean attribute by unit and season (x10 scale / 10). OL: RunBlk 30, HandUse 32, Anchor 33, Strength 3, PassBlk 29, Speed 0
rsql with p as (select lp.season s, lp.person__player__position pos, more('log_players', lp._more) m from log_players lp where lp.level = 'NFL' and lp.overall >= 76 and lp.person__player__position in ('OT','IOL')) select s, count(*) n, round(avg(json_extract(m,'$.person.player.attributes_x10[30]'))/10,2) run_blk, round(avg(json_extract(m,'$.person.player.attributes_x10[32]'))/10,2) hand_use, round(avg(json_extract(m,'$.person.player.attributes_x10[33]'))/10,2) anchor, round(avg(json_extract(m,'$.person.player.attributes_x10[3]'))/10,2) strength, round(avg(json_extract(m,'$.person.player.attributes_x10[29]'))/10,2) pass_blk, round(avg(json_extract(m,'$.person.player.attributes_x10[31]'))/10,2) in_space, round(avg(json_extract(m,'$.person.player.attributes_x10[0]'))/10,2) speed from p group by s order by s
-- DL and LB: BlockShed 36, Strength 3, PowerRush 34, Finesse 35, Tackling 41, Pursuit 42, Traffic 44, Speed 0
rsql with p as (select lp.season s, case when lp.person__player__position in ('DT','EDGE') then 'DL' else 'LB' end u, more('log_players', lp._more) m from log_players lp where lp.level = 'NFL' and lp.overall >= 76 and lp.person__player__position in ('DT','EDGE','LB')) select u, s, count(*) n, round(avg(json_extract(m,'$.person.player.attributes_x10[36]'))/10,2) shed, round(avg(json_extract(m,'$.person.player.attributes_x10[3]'))/10,2) strength, round(avg(json_extract(m,'$.person.player.attributes_x10[34]'))/10,2) power_rush, round(avg(json_extract(m,'$.person.player.attributes_x10[35]'))/10,2) finesse, round(avg(json_extract(m,'$.person.player.attributes_x10[41]'))/10,2) tackling, round(avg(json_extract(m,'$.person.player.attributes_x10[42]'))/10,2) pursuit, round(avg(json_extract(m,'$.person.player.attributes_x10[0]'))/10,2) speed, round(avg(json_extract(m,'$.person.player.attributes_x10[33]'))/10,2) anchor from p group by u, s order by u, s
-- RB and S and CB: Vision 20, Elusive 21, LegDrive 22, Speed 0, Accel 1, Tackling 41, Pursuit 42
rsql with p as (select lp.season s, lp.person__player__position u, more('log_players', lp._more) m from log_players lp where lp.level = 'NFL' and lp.overall >= 76 and lp.person__player__position in ('RB','S','CB')) select u, s, count(*) n, round(avg(json_extract(m,'$.person.player.attributes_x10[20]'))/10,2) vision, round(avg(json_extract(m,'$.person.player.attributes_x10[21]'))/10,2) elusive, round(avg(json_extract(m,'$.person.player.attributes_x10[22]'))/10,2) leg_drive, round(avg(json_extract(m,'$.person.player.attributes_x10[0]'))/10,2) speed, round(avg(json_extract(m,'$.person.player.attributes_x10[1]'))/10,2) accel, round(avg(json_extract(m,'$.person.player.attributes_x10[41]'))/10,2) tackling, round(avg(json_extract(m,'$.person.player.attributes_x10[42]'))/10,2) pursuit from p group by u, s order by u, s
